package com.farmtech.farmhub.api

import com.farmtech.farmhub.models.auth.GenericStatusResponse
import com.farmtech.farmhub.models.auth.ResetPasswordRequest
import com.farmtech.farmhub.models.login.LoginRequest
import com.farmtech.farmhub.models.login.LoginResponse
import com.farmtech.farmhub.models.message.SendMessageResponse
import com.farmtech.farmhub.models.media.MediaFeedResponse
import com.farmtech.farmhub.models.posts.CreatePostResponse
import com.farmtech.farmhub.models.posts.GetAllPostsResponse
import com.farmtech.farmhub.models.posts.PostDetailResponse
import com.farmtech.farmhub.models.profile.UserProfileResponse
import com.farmtech.farmhub.models.signup.RegisterRequest
import com.farmtech.farmhub.models.signup.RegisterResponse
import com.farmtech.farmhub.models.geo.CountiesResponse
import com.farmtech.farmhub.models.messaging.MessagesResponse
import com.farmtech.farmhub.models.messaging.ThreadListResponse
import com.farmtech.farmhub.models.weather.WeatherForecastResponse
import okhttp3.MultipartBody
import okhttp3.RequestBody
import retrofit2.Call
import retrofit2.http.Body
import retrofit2.http.GET
import retrofit2.http.Multipart
import retrofit2.http.POST
import retrofit2.http.Part
import retrofit2.http.Path
import retrofit2.http.Query

interface UserService {

    @POST("auth/login")
    fun userLogin(@Body loginRequest: LoginRequest): Call<LoginResponse>

    @POST("auth/register")
    fun registerUser(@Body registerRequest: RegisterRequest): Call<RegisterResponse>

    @GET("auth/me")
    fun getUserProfile(): Call<UserProfileResponse>

    @GET("posts")
    fun getAllPosts(): Call<GetAllPostsResponse>

    @Multipart
    @POST("posts")
    fun createPost(
        @Part image: MultipartBody.Part,
        @Part("description") description: RequestBody
    ): Call<CreatePostResponse>

    @Multipart
    @POST("messaging")
    fun sendMessageWithAttachment(
