            val uploadButtonModifier = Modifier
                .fillMaxWidth()
                .heightIn(min = 54.dp)

            Button(
                onClick = onCamera,
                modifier = uploadButtonModifier,
                colors = ButtonDefaults.buttonColors(
                    containerColor = orangeAccent,
                    contentColor = onOrangeAccent
