    ) {
        repeat(totalSteps) { index ->
            Box(
                modifier = Modifier
                    .size(12.dp)
                    .padding(4.dp)
                    .background(
                        if (index + 1 <= currentStep) activeColor else inactiveColor,
                        shape = CircleShape
                    )
            )
        }
    }
}

