@Composable private fun IntroFeatureCard( logoRes: Int, logoContentDescription: String, message: String, accentColor: Color, compact: Boolean, onClick: () -> Unit ) { val interactionSource = remember { MutableInteractionSource() } val pressed by interactionSource.collectIsPressedAsState() val scale by animateFloatAsState( targetValue = if (pressed) 0.985f else 1f, animationSpec = spring(stiffness = 500f, dampingRatio = 0.8f), label = "introCardScale" ) val elevation by animateDpAsState( targetValue = if (pressed) 2.dp else 5.dp, animationSpec = spring(stiffness = 500f, dampingRatio = 0.85f), label = "introCardElevation" )
val logoHeight = if (compact) 46.dp else 54.dp val logoWidthRatio = if (compact) 0.52f else 0.56f val messageFont = if (compact) 16.sp else 18.sp val lineHeight = if (compact) 22.sp else 25.sp val verticalPadding = if (compact) 14.dp else 18.dp
ElevatedCard( modifier = Modifier .fillMaxWidth() .scale(scale) .clickable( interactionSource = interactionSource, indication = null, onClick = onClick ) .border( width = 1.dp, color = accentColor.copy(alpha = 0.2f), shape = RoundedCornerShape(18.dp) ), shape = RoundedCornerShape(18.dp), colors = CardDefaults.elevatedCardColors(containerColor = MaterialTheme.colorScheme.surface), elevation = CardDefaults.elevatedCardElevation(defaultElevation = elevation) ) { Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp, vertical = verticalPadding), horizontalAlignment = Alignment.CenterHorizontally ) { Image( painter = painterResource(id = logoRes), contentDescription = logoContentDescription, modifier = Modifier .height(logoHeight) .fillMaxWidth(logoWidthRatio) )
Spacer(modifier = Modifier.height(if (compact) 8.dp else 12.dp))
Text( text = message, style = MaterialTheme.typography.titleMedium.copy(fontSize = messageFont), fontWeight = FontWeight.SemiBold, textAlign = TextAlign.Center, color = MaterialTheme.colorScheme.onSurface, lineHeight = lineHeight ) }
} }

