@Composable
private fun VideoResults(
    navController: NavHostController,
    selectionTitle: String,
    selectionDescription: String,
    videos: List<VideoItem>,
    errorMessage: String?,
    hasMore: Boolean,
    onRetry: () -> Unit,
    onLoadMore: () -> Unit
) {
    LazyColumn(
        verticalArrangement = Arrangement.spacedBy(12.dp),
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 12.dp, vertical = 10.dp)
    ) {
        item {
            SelectionSummaryCard(
                selectionTitle = selectionTitle,
                selectionDescription = selectionDescription,
                totalVideos = videos.size,
                onRetry = onRetry
            )
        }

        if (errorMessage != null) {
            item {
                ErrorBanner(message = errorMessage, onRetry = onRetry)
            }
        }

        if (videos.isEmpty()) {
            item {
                EmptyMediaState(selectionTitle = selectionTitle, retry = onRetry)
            }
        } else {
            items(videos, key = { it.id }) { video ->
                VideoCard(video = video) {
                    navController.navigate(AppRoutes.VIDEO_DETAIL.replace("{videoId}", video.id.toString()))
                }
            }
        }

        if (hasMore) {
            item {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                    horizontalArrangement = Arrangement.Center,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedButton(onClick = onLoadMore) {
                        Text("Load more")
                    }
                }
            }
        }
    }
}

@Composable
private fun SelectionSummaryCard(
    selectionTitle: String,
    selectionDescription: String,
    totalVideos: Int,
    onRetry: () -> Unit
) {
    val videosAccent = MaterialTheme.colorScheme.tertiary

    Card(
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = selectionTitle,
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = selectionDescription,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
                AssistChip(
                    onClick = {},
                    label = { Text("$totalVideos videos") },
                    colors = AssistChipDefaults.assistChipColors(
                        containerColor = videosAccent.copy(alpha = 0.12f),
                        labelColor = videosAccent
                    )
                )
            }
            Spacer(modifier = Modifier.height(12.dp))
            TextButton(onClick = onRetry, modifier = Modifier.align(Alignment.End)) {
                Text("Refresh feed")
            }
        }
    }
}

@Composable
private fun ErrorBanner(message: String, onRetry: () -> Unit) {
    Card(
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(14.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = message,
                modifier = Modifier.weight(1f),
                color = MaterialTheme.colorScheme.onErrorContainer,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis
            )
            Spacer(modifier = Modifier.width(12.dp))
            OutlinedButton(onClick = onRetry) {
                Text("Retry")
            }
        }
    }
}

@Composable
private fun LoadingState() {
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        item {
            Row(verticalAlignment = Alignment.CenterVertically) {
                CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
                Spacer(Modifier.width(8.dp))
                Text("Loading FarmVideos...", style = MaterialTheme.typography.bodyMedium)
            }
        }
        items(4) {
            Card(shape = RoundedCornerShape(16.dp), modifier = Modifier.fillMaxWidth()) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(160.dp)
                            .background(MaterialTheme.colorScheme.surfaceVariant)
                    )
                    Spacer(Modifier.height(10.dp))
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(0.8f)
                            .height(16.dp)
                            .background(MaterialTheme.colorScheme.surfaceVariant)
                    )
                    Spacer(Modifier.height(8.dp))
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(0.5f)
                            .height(12.dp)
                            .background(MaterialTheme.colorScheme.surfaceVariant)
                    )
                }
            }
        }
    }
}

@Composable
private fun EmptyMediaState(selectionTitle: String, retry: () -> Unit) {
    val videosAccent = MaterialTheme.colorScheme.tertiary

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 28.dp, horizontal = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Icon(
            imageVector = Icons.Default.PlayCircle,
            contentDescription = "No videos",
            modifier = Modifier.size(64.dp),
            tint = videosAccent
        )
        Spacer(Modifier.height(10.dp))
        Text(
            text = "No videos for $selectionTitle yet",
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.SemiBold,
            textAlign = TextAlign.Center
        )
        Spacer(Modifier.height(6.dp))
        Text(
            text = "Try another category from the drawer or refresh to check for newly published content.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            textAlign = TextAlign.Center
        )
        Spacer(Modifier.height(14.dp))
        OutlinedButton(onClick = retry) {
            Text("Retry")
        }
    }
}

