) {
    var showFarmHelp by remember { mutableStateOf(false) }
    val farmHelpViewModel: FarmHelpViewModel = viewModel()
    val primaryGreen = MaterialTheme.colorScheme.primary
    val orangeAccent = MaterialTheme.colorScheme.tertiary
    val onOrangeAccent = MaterialTheme.colorScheme.onTertiary
    val orangeContainer = MaterialTheme.colorScheme.tertiaryContainer
    val onOrangeContainer = MaterialTheme.colorScheme.onTertiaryContainer

    val exploreItems = remember {
        listOf(
            ExploreItem(
                title = "Watch FREE Farming Videos",
                description = "Learn practical techniques from trusted local experts.",
                icon = Icons.Default.PlayCircle,
                onClick = onVideosClick
            ),
            ExploreItem(
                title = "AgriConnect",
                description = "Start a conversation with an extension officer.",
                icon = Icons.AutoMirrored.Filled.Chat,
                onClick = onChatClick
            ),
            ExploreItem(
                title = "Weather Forecast",
                description = "Get location-aware weather insights for your planning.",
                icon = Icons.Default.WbSunny,
                onClick = {}
            ),
            ExploreItem(
                title = "Tip of the Day",
                description = "Seasonal guidance to improve crop and livestock outcomes.",
                icon = Icons.Default.TipsAndUpdates,
                onClick = {}
            )
        )
    }

    Surface(
        modifier = Modifier.fillMaxSize(),
        color = MaterialTheme.colorScheme.background
    ) {
        Box(modifier = Modifier.fillMaxSize()) {

            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 16.dp)
            ) {
                Text(
                    text = "FarmHelp",
                    style = MaterialTheme.typography.headlineMedium,
                    fontWeight = FontWeight.Bold,
                    color = primaryGreen,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 24.dp, bottom = 8.dp)
                )
                OutlinedCard(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                    shape = RoundedCornerShape(12.dp),
                    border = BorderStroke(1.dp, orangeAccent.copy(alpha = 0.3f)),
                    elevation = CardDefaults.outlinedCardElevation(defaultElevation = 2.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = orangeContainer.copy(alpha = 0.35f)
                    )
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.padding(bottom = 8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.Chat,
                                contentDescription = "Help",
                                tint = orangeAccent,
                                modifier = Modifier.size(24.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = "Facing Farming Challenges?",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.SemiBold,
                                color = orangeAccent
                            )
                        }
                        Text(
