import androidx.compose.ui.platform.LocalContext
import kotlinx.coroutines.launch

@Composable
fun ProfileScreen(
    onToggleTheme: () -> Unit,
    isLoggedIn: Boolean,
    onSignInClick: () -> Unit,
    onSignOutClick: () -> Unit,
    viewModel: ProfileViewModel = viewModel()
) {
    LaunchedEffect(Unit) {
        viewModel.fetchProfile()
    }

    val profile = viewModel.profile
    val error = viewModel.error
    val isLoading = viewModel.isLoading
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    // No Scaffold, header, or bottom nav here. Only content.
    Column(
        modifier = Modifier
            .fillMaxSize()
    ) {
        // Cover Photo
        Box(modifier = Modifier
            .fillMaxWidth()
            .height(200.dp)) {
            Image(
                painter = painterResource(id = R.drawable.ic_launcher_background),
                contentDescription = "Cover Photo",
                contentScale = ContentScale.Crop,
                modifier = Modifier.fillMaxSize()
            )

            // Profile Photo
            Box(
                modifier = Modifier
                    .size(100.dp)
                    .align(Alignment.BottomCenter)
                    .offset(y = 50.dp)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.surface),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painter = painterResource(id = R.drawable.ic_launcher_foreground),
                    contentDescription = "Profile Photo",
                    contentScale = ContentScale.Crop,
                    modifier = Modifier
                        .size(92.dp)
                        .clip(CircleShape)
                )
            }
        }

        Spacer(modifier = Modifier.height(60.dp))

        // Username and Email
        Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
            if (isLoading) {
                CircularProgressIndicator(modifier = Modifier.size(32.dp))
            }

            if (error != null) {
                Text("Error: $error", color = MaterialTheme.colorScheme.error)
            }

            if (profile != null) {
                Text(profile.names, fontSize = 20.sp, fontWeight = FontWeight.Bold)
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Default.Email, contentDescription = "Email", modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(profile.phone, fontSize = 14.sp)
                }
                Spacer(modifier = Modifier.height(8.dp))
                if (profile.county != null) {
                    Text("County: ${profile.county}", fontSize = 14.sp)
                }
                if (profile.subCounty != null) {
                    Text("SubCounty: ${profile.subCounty}", fontSize = 14.sp)
                }
                Spacer(modifier = Modifier.height(6.dp))
                Text("Subscription Status: ${profile.paymentStatus}", fontSize = 14.sp)
            }
        }

        Spacer(modifier = Modifier.height(32.dp))

        // Preferences / Settings
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            PreferenceItem(icon = Icons.Default.Notifications, title = "Notifications") { }
            PreferenceItem(icon = Icons.Default.DarkMode, title = "Dark Mode") { onToggleTheme() }
            PreferenceItem(icon = Icons.Default.Language, title = "Language") { }
            PreferenceItem(icon = Icons.Default.Settings, title = "Account Settings") { }
        }

        Spacer(modifier = Modifier.height(32.dp))

        // Auth toggle button
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Center
        ) {
            if (isLoggedIn) {
                Button(
                    onClick = {
                        scope.launch {
                            AuthManager.logout(context)
                            onSignOutClick()
                        }
                    }
                ) {
                    Text("Sign Out")
                }
            } else {
                Button(
                    onClick = onSignInClick
                ) {
                    Text("Sign In")
                }
            }
        }
    }
}

@Composable
fun PreferenceItem(icon: ImageVector, title: String, onClick: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Icon(
            imageVector = icon,
            contentDescription = title,
            modifier = Modifier.size(24.dp)
        )
        Spacer(modifier = Modifier.width(16.dp))
        Text(title, fontSize = 16.sp)
    }
}

package com.farmtech.farmhub.ui.tabs

import coil.compose.AsyncImage
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.ExpandLess
import androidx.compose.material.icons.filled.ExpandMore
import androidx.compose.material.icons.filled.PlayArrow
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.lifecycle.viewmodel.compose.viewModel
import com.farmtech.farmhub.models.VideoViewModel
import com.farmtech.farmhub.ui.components.VideoCard
import com.farmtech.farmhub.ui.components.VideoPlayer
import com.farmtech.farmhub.viewmodel.MediaUiState
import com.farmtech.farmhub.viewmodel.MediaViewModel

@Composable
fun VideoDetailScreen(
    videoId: Int,
    onVideoClick: (Int) -> Unit,
    videoViewModel: VideoViewModel = viewModel(),
    mediaViewModel: MediaViewModel = viewModel()
) {
    var commentsExpanded by remember { mutableStateOf(false) }
    val videosAccent = MaterialTheme.colorScheme.tertiary
    val onVideosAccent = MaterialTheme.colorScheme.onTertiary

    val mediaState = mediaViewModel.uiState.collectAsState()

    // Ensure media loaded so remote id can be found
    LaunchedEffect(Unit) {
        if (mediaState.value is MediaUiState.Idle) {
            mediaViewModel.loadMedia()
        }
    }

    // Try remote first, then fallback to static
    val remoteVideo = mediaViewModel.getVideoById(videoId)
    val video = remoteVideo ?: videoViewModel.getVideoById(videoId)
    val relatedVideos = if (remoteVideo != null) {
        // Use other remote videos (simple exclusion)
        mediaViewModel.allVideos().filter { it.id != videoId }.take(10)
    } else {
        videoViewModel.getRelatedVideos(videoId)
    }
    val comments = videoViewModel.comments // still using static comments

    if (video == null) {
        // Show loading if remote list still loading
        if (mediaState.value is MediaUiState.Loading) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    CircularProgressIndicator()
                    Spacer(Modifier.height(12.dp))
                    Text("Loading video...")
                }
            }
        } else {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) { Text("Video not found", fontSize = 18.sp) }
        }
        return
    }

    LazyColumn(
        verticalArrangement = Arrangement.spacedBy(12.dp),
        modifier = Modifier
            .fillMaxSize()
            .padding(12.dp)
    ) {
        item {
            Card(
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .height(200.dp)
                    .padding(bottom = 12.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
            ) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    val mediaUrl = video.mediaUrl
                    if (!mediaUrl.isNullOrBlank()) {
                        VideoPlayer(url = mediaUrl, modifier = Modifier.fillMaxSize())
                    } else if (video.thumbnailUrl != null) {
                        AsyncImage(
                            model = video.thumbnailUrl,
                            contentDescription = video.title,
                            modifier = Modifier.fillMaxSize(),
                            contentScale = ContentScale.Crop
                        )
                    } else {
                        Icon(
                            imageVector = Icons.Default.PlayArrow,
                            contentDescription = "Video Placeholder",
                            modifier = Modifier.size(64.dp),
                            tint = videosAccent
                        )
                    }
                }
            }
        }
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 8.dp)
            ) {
                Text(
                    text = video.title,
                    fontSize = 22.sp,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Box(
                        modifier = Modifier
                            .size(36.dp)
                            .background(videosAccent, RoundedCornerShape(18.dp)),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = video.channel.firstOrNull()?.toString() ?: "?",
                            color = onVideosAccent,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Spacer(modifier = Modifier.width(10.dp))
                    Text(
                        text = video.channel,
                        fontWeight = FontWeight.Medium,
                        fontSize = 16.sp
                    )
                    Spacer(modifier = Modifier.weight(1f))
                }
                Spacer(modifier = Modifier.height(6.dp))
                Text(
                    text = listOfNotNull(video.views.takeIf { it.isNotBlank() }, video.time.takeIf { it.isNotBlank() }).joinToString(" • "),
                    fontSize = 15.sp,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                )
            }
            HorizontalDivider(thickness = 1.dp)
        }

        item {
            Card(
                shape = RoundedCornerShape(14.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 8.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(14.dp)
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { commentsExpanded = !commentsExpanded }
                    ) {
                        Text(
                            "Comments (${comments.size})",
                            fontWeight = FontWeight.Bold,
                            fontSize = 17.sp
                        )
                        Spacer(modifier = Modifier.weight(1f))
                        Icon(
                            imageVector = if (commentsExpanded) Icons.Default.ExpandLess else Icons.Default.ExpandMore,
                            contentDescription = if (commentsExpanded) "Collapse" else "Expand"
                        )
                    }
                    if (commentsExpanded) {
                        Spacer(modifier = Modifier.height(10.dp))
                        comments.forEach { comment ->
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 6.dp)
                            ) {
                                Text(comment.user, fontWeight = FontWeight.Bold)
                                Text(comment.text, fontSize = 15.sp)
                            }
                            HorizontalDivider(thickness = 0.5.dp)
                        }
                    }
                }
            }
            HorizontalDivider(thickness = 1.dp)
        }

        item {
            Text(
                "Related Videos",
                fontSize = 19.sp,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(vertical = 8.dp)
            )
        }

        items(relatedVideos) { videoItem ->
            VideoCard(
                video = videoItem,
                onClick = { onVideoClick(videoItem.id) }
            )
            HorizontalDivider(thickness = 0.5.dp)
        }
    }
}

